import{_ as o,r as n,o as l,c as p,e as a,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Relation Field - October CMS - 3.x","titleTemplate":false,"description":"Form Widget","frontmatter":{"subtitle":"Form Widget","shortname":"Relation"},"headers":[{"level":2,"title":"Applying Conditions","slug":"applying-conditions","link":"#applying-conditions","children":[{"level":3,"title":"SQL Query Condition","slug":"sql-query-condition","link":"#sql-query-condition","children":[]},{"level":3,"title":"PHP Query Scopes","slug":"php-query-scopes","link":"#php-query-scopes","children":[]}]},{"level":2,"title":"Relation Controller Integration","slug":"relation-controller-integration","link":"#relation-controller-integration","children":[]}],"relativePath":"3.x/element/form/widget-relation.md","filePath":"3.x/element/form/widget-relation.md"}'),i={name:"3.x/element/form/widget-relation.md"};function d(u,e,k,y,m,h){const t=n("pre-heading"),s=n("post-heading");return l(),p("div",null,[a(t),e[0]||(e[0]=c("h1",null,"Relation Field",-1)),a(s),e[1]||(e[1]=r(`<p><code>relation</code> - renders either a dropdown or checkbox list according to the field relation type. Singular relationships display a dropdown, multiple relationships display a checkbox list. The label used for displaying each relation is sourced by the <code>nameFrom</code> or <code>select</code> definition.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">categories</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Categories
    <span class="token key atrule">type</span><span class="token punctuation">:</span> relation
</code></pre></div><p>The following <a href="./../form-fields.html">field properties</a> are supported and commonly used.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>a name when displaying the form field to the user.</td></tr><tr><td><strong>comment</strong></td><td>places a descriptive comment below the field.</td></tr><tr><td><strong>nameFrom</strong></td><td>a model attribute name used for displaying the relation label. Default: <code>name</code>.</td></tr><tr><td><strong>excludeFrom</strong></td><td>a parent model attribute used to exclude related keys in the list, optional.</td></tr><tr><td><strong>select</strong></td><td>a custom SQL select statement to use for the name.</td></tr><tr><td><strong>emptyOption</strong></td><td>text to display when there is no available selections.</td></tr><tr><td><strong>conditions</strong></td><td>specifies a raw where query statement to apply to the model query.</td></tr><tr><td><strong>modelScope</strong></td><td>applies a <a href="./../../extend/database/model.html">model query scope</a> method to the <strong>related form model</strong>, can be a model method name or a static PHP class method (<code>Class::method</code>).</td></tr><tr><td><strong>defaultSort</strong></td><td>sets a default sorting column and direction, supports a string for the column name or an array with keys <code>column</code> and <code>direction</code>. The direction can be <code>asc</code> for ascending (default) or <code>desc</code> for descending order.</td></tr><tr><td><strong>useController</strong></td><td>automatically detects if this field configured with <a href="./../../extend/forms/relation-controller.html">Relation Controller behavior</a> and use it. Default: <code>true</code></td></tr><tr><td><strong>controller</strong></td><td>specifies an array to manually configure integration with the <a href="./../../extend/forms/relation-controller.html">Relation Controller behavior</a>.</td></tr></tbody></table></div><p>Use the <code>nameFrom</code> property to customize the label used for the related record.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">categories</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Categories
    <span class="token key atrule">type</span><span class="token punctuation">:</span> relation
    <span class="token key atrule">nameFrom</span><span class="token punctuation">:</span> title
</code></pre></div><p>Alternatively, you may populate the label using a custom <code>select</code> statement. Any valid SQL statement works here.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">user</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> User
    <span class="token key atrule">type</span><span class="token punctuation">:</span> relation
    <span class="token key atrule">select</span><span class="token punctuation">:</span> concat(first_name<span class="token punctuation">,</span> <span class="token string">&#39; &#39;</span><span class="token punctuation">,</span> last_name)
</code></pre></div><h2 id="applying-conditions"><a href="#applying-conditions" class="header-anchor">#</a> Applying Conditions</h2><p>You can filter the available records using SQL or PHP conditions using the approaches below.</p><h3 id="sql-query-condition"><a href="#sql-query-condition" class="header-anchor">#</a> SQL Query Condition</h3><p>You may limit the related model using a raw SQL query using the <code>conditions</code> property.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">user</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> User
    <span class="token key atrule">type</span><span class="token punctuation">:</span> relation
    <span class="token key atrule">conditions</span><span class="token punctuation">:</span> is_featured = true
</code></pre></div><p>The value also supports simple parameters parsed from the parent model attributes. The parameter names begin with a colon (<code>:</code>) character.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">country</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Country
    <span class="token key atrule">type</span><span class="token punctuation">:</span> relation

<span class="token key atrule">state</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> State
    <span class="token key atrule">type</span><span class="token punctuation">:</span> relation
    <span class="token key atrule">dependsOn</span><span class="token punctuation">:</span> country
    <span class="token key atrule">conditions</span><span class="token punctuation">:</span> custom_country_id = <span class="token punctuation">:</span>country_id
</code></pre></div><h3 id="php-query-scopes"><a href="#php-query-scopes" class="header-anchor">#</a> PHP Query Scopes</h3><p>You can provide a model scope to use to filter the results with the <code>modelScope</code> property.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">user</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> User
    <span class="token key atrule">type</span><span class="token punctuation">:</span> relation
    <span class="token key atrule">modelScope</span><span class="token punctuation">:</span> withTrashed
</code></pre></div><p>The <code>modelScope</code> can be used to connect two related fields, for example, connecting a <code>Country</code> and <code>State</code> model, where the available states are filtered by the selected country. The <code>dependsOn</code> property enables <a href="./../../extend/forms/field-dependencies.html">field dependencies</a> and updates the <code>state</code> options when a <code>country</code> is selected.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">country</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Country
    <span class="token key atrule">type</span><span class="token punctuation">:</span> relation

<span class="token key atrule">state</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> State
    <span class="token key atrule">type</span><span class="token punctuation">:</span> relation
    <span class="token key atrule">dependsOn</span><span class="token punctuation">:</span> country
    <span class="token key atrule">modelScope</span><span class="token punctuation">:</span> filterStates
</code></pre></div><p>The <code>modelScope</code> value <strong>filterStates</strong> translates to the <code>scopeFilterStates</code> method defined in the <code>State</code> model. The <code>$model</code> (second argument) supplied to the <a href="./../../extend/database/model.html">model query scope</a> lets you capture the selected country and filter the available options.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">scopeFilterStates</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$countryId</span> <span class="token operator">=</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">country_id</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;country_id&#39;</span><span class="token punctuation">,</span> <span class="token variable">$countryId</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="relation-controller-integration"><a href="#relation-controller-integration" class="header-anchor">#</a> Relation Controller Integration</h2><p>If the controller implements the <a href="./../../extend/forms/relation-controller.html">Relation Controller behavior</a> and the field is defined there, then it will be displayed using this definition. Set the <code>useController</code> property to false to disable this functionality.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">countries</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Categories
    <span class="token key atrule">type</span><span class="token punctuation">:</span> relation
    <span class="token key atrule">useController</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><p>The <code>controller</code> property may be used to specify inline configuration.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">products</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Products
    <span class="token key atrule">tab</span><span class="token punctuation">:</span> Products
    <span class="token key atrule">type</span><span class="token punctuation">:</span> relation
    <span class="token key atrule">controller</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Product
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/october/test/models/product/columns.yaml
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/october/test/models/product/fields.yaml
</code></pre></div>`,27))])}const b=o(i,[["render",d]]);export{f as __pageData,b as default};
